import { ChevronRight } from "lucide-react";
import Link from "next/link";
import type { CredlyBadgeItem } from "../../../lib/portfolio/credly";
import Image from "next/image";

export default function CertificateBadge({
  item,
}: Readonly<{ item: CredlyBadgeItem }>) {
  const badge = item;

  const date = item.issued_at
    ? new Date(item.issued_at).toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      })
    : "—";

  const shortId = item.id?.slice(-8).toUpperCase() ?? "—";

  // Credly's public verify URL pattern
  const verifyUrl = `https://www.credly.com/badges/${item.id}/public_url`;

  return (
    <div className="border group transition-colors duration-300 flex items-center  hover:bg-white/2  p-6  border-slate-600/50 hover:border-blue-400/50">
      {/* Header Row */}
      <div className="flex items-center gap-6 ">
        <div className="p-3  scale-110 transition-transform duration-500 shrink-0">
          {badge.image_url ? (
            <Image
              src={badge.image_url}
              alt={badge.name}
              width={160}
              height={160}
              className="size-30 md:size-40 object-contain"
            />
          ) : (
            <span className="text-2xl">🏅</span>
          )}
        </div>

        <div className="grow min-w-0">
          <div className="mb-4 ">
            <div className="flex items-center gap-2 mb-1 ">
              <span className="text-[11px] font-medium text-zinc-500 uppercase tracking-wider group-hover:text-white">
                {date}
              </span>
              <span className="text-[10px] font-mono text-zinc-600 uppercase tracking-widest group-hover:text-white">
                ID: {shortId}
              </span>
            </div>
            <h3 className="text-2xl md:text-3xl font-bold text-white group-hover:text-blue-400 transition-colors">
              {badge.name}
            </h3>
          </div>

          <div className="max-w-4xl ">
            {badge.description && (
              <p className="text-sm text-zinc-500 leading-relaxed  group-hover:text-white line-clamp-3 mt-4 mb-4">
                {badge.description}
              </p>
            )}

            {/* Footer Info Row */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between pt-4 border-t border-white/5 gap-4">
              <div className="flex items-center gap-2 shrink-0">
                <Link
                  href={verifyUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 text-sm   tracking-[0.2em] text-white/60 hover:text-blue-400 transition-all group/link group-hover:text-white"
                >
                  View Certificate
                  <ChevronRight
                    size={14}
                    className="group-hover/link:translate-x-1 transition-transform"
                  />
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

@theme inline {
  --color-primary-light: var(--primary);
  --color-primary-hover: var(--primary);
  --color-accent-cyan: var(--secondary);
  --color-accent-purple: var(--primary);
  --color-info: var(--primary);
  --shadow-glow: 0 0 20px color-mix(in oklab, var(--primary) 15%, transparent);
  --shadow-glow-lg: 0 0 30px color-mix(in oklab, var(--primary) 25%, transparent);
  --font-heading: var(--font-sans);
}

@layer components {
  /* Example utility combining the new theme variables */
  .btn-primary-glow {
    @apply bg-primary text-primary-foreground shadow-glow hover:shadow-glow-lg
           transition-all duration-200 active:scale-95;
  }

  .blog-content > table,
  .blog-content > .table-wrapper > table {
    width: 100%;
    margin: 2rem 0;
    border-collapse: separate;
    border-spacing: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    background: color-mix(in oklab, var(--background) 60%, transparent);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.08);
    font-size: 0.95rem;
  }

  .blog-content > table[header-row="true"] tbody tr:first-child td,
  .blog-content > table thead th,
  .blog-content > .table-wrapper > table[header-row="true"] tbody tr:first-child td,
  .blog-content > .table-wrapper > table thead th {
    background: color-mix(in oklab, var(--muted) 40%, transparent);
    color: var(--foreground);
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  .blog-content > table td,
  .blog-content > table th,
  .blog-content > .table-wrapper > table td,
  .blog-content > .table-wrapper > table th {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    color: var(--muted-foreground);
  }

  .blog-content > table tr:last-child td,
  .blog-content > table tr:last-child th,
  .blog-content > .table-wrapper > table tr:last-child td,
  .blog-content > .table-wrapper > table tr:last-child th {
    border-bottom: 0;
  }

  .blog-content > table td code,
  .blog-content > table th code,
  .blog-content > .table-wrapper > table td code,
  .blog-content > .table-wrapper > table th code {
    display: inline-block;
    padding: 0.1rem 0.35rem;
    border-radius: calc(var(--radius) * 0.45);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 0.85em;
    font-weight: 600;
  }


}

interface CredlyBadgeTemplate {
  name: string;
  description?: string;
  image_url?: string;
  issuer?: {
    name: string;
  };
}

interface CredlyBadgeResponse {
  id: string;
  issued_at?: string;
  badge_template: CredlyBadgeTemplate;
}

export interface CredlyBadgeItem {
  id: string;
  name: string;
  description?: string;
  image_url?: string;
  issuer?: {
    name: string;
  };
  issued_at?: string;
}

const CREDLY_URL =
  "https://www.credly.com/users/e17d1c8e-ffef-44e7-b80d-5897e1d3c823/badges.json";

export async function getCredlyBadges(): Promise<CredlyBadgeItem[]> {
  const res = await fetch(CREDLY_URL, {
    headers: { Accept: "application/json" },
    next: { revalidate: 3600 },
  });

  if (!res.ok) throw new Error(`Credly fetch failed: ${res.status}`);

  const data = await res.json();
  const badges = data.data as CredlyBadgeResponse[];

  // Transform nested structure into flat structure
  return badges.map((badge) => ({
    id: badge.id,
    name: badge.badge_template.name,
    description: badge.badge_template.description,
    image_url: badge.badge_template.image_url,
    issuer: badge.badge_template.issuer,
    issued_at: badge.issued_at,
  }));
}
